$('save').onclick=()=>{let x={id:$('editId').value,name:$('editName').value,level:$('editLevel').value,avoid:$('editAvoid').value,source:$('editSource').value,version:$('editVersion').value,evidence:$('editEvidence').value,state:$('editState').value,category:$('editCategory').value,presence:$('editPresence').value};if(!valid(x)){$('editMessage').textContent='ID, 이름, 레벨, 회피율을 올바르게 입력해 주세요.';return}x=normal(x);if(!supplied.some(item=>item.id===x.id)){$('editMessage').textContent='제공하신 파일에 있는 몬스터 ID만 수정할 수 있습니다.';return}if(x.state==='external'&&!x.evidence.trim())x.state='review';if((x.state==='verified'||x.state==='modified'||x.state==='external'||x.state==='difference'||x.presence!=='unknown'||x.category!=='unknown')&&!x.evidence.trim()){$('editMessage').textContent='검증 상태, 분류 또는 등장 여부의 근거를 실게임 검증 기록에 입력해 주세요.';return}if(persist({...overrides,[x.id]:x})){selected=x.id;$('editMessage').textContent='저장했습니다.';show()}};
