$('reset').onclick=()=>{if(!overrides[selected]){$('editMessage').textContent='선택한 항목에 저장된 수정값이 없습니다.';return}let next={...overrides};delete next[selected];if(persist(next)){let m=entries().find(x=>x.id===selected);if(!m)selected=seed[0].id;fill(entries().find(x=>x.id===selected));$('editMessage').textContent='수정값을 되돌렸습니다.';show()}};
function parseCSV(t){let rows=[],row=[],cell='',quote=false;t=t.replace(/^\uFEFF/,'');for(let i=0;i<t.length;i++){let c=t[i];if(quote){if(c==='"'&&t[i+1]==='"'){cell+='"';i++}else if(c==='"')quote=false;else cell+=c}else if(c==='"'){if(cell!=='')throw Error('CSV 따옴표 형식 오류');quote=true}else if(c===','){row.push(cell);cell=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&t[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quote)throw Error('닫히지 않은 따옴표');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(rows.length<2)throw Error('데이터가 없습니다');let h=rows.shift().map(x=>x.trim());if(!['id','name','level','avoid'].every(x=>h.includes(x)))throw Error('필수 열이 없습니다');return rows.map(r=>Object.fromEntries(h.map((k,i)=>[k,r[i]??''])))}
$('import').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('파일이 너무 큽니다 (최대 5MB).');let text=await file.text();let data=file.name.toLowerCase().endsWith('.json')?JSON.parse(text):parseCSV(text);if(!Array.isArray(data)||!data.length)throw Error('배열 또는 CSV 데이터가 필요합니다.');let seen=new Set();for(let [i,x] of data.entries()){if(!valid(x))throw Error(`${i+1}번째 항목의 필수 값이 잘못되었습니다.`);if(!supplied.some(item=>item.id===Number(x.id)))throw Error(`${i+1}번째 항목의 ID가 제공하신 파일에 없습니다.`);if(seen.has(Number(x.id)))throw Error(`${i+1}번째 항목의 ID가 파일 안에서 중복됩니다.`);seen.add(Number(x.id))}let next={...overrides};data.forEach(x=>{x=normal(x);if((x.state==='verified'||x.state==='modified'||x.state==='external'||x.state==='difference'||x.category!=='unknown'||x.presence!=='unknown')&&!x.evidence.trim()){x.state='review';x.category='unknown';x.presence='unknown'}next[x.id]=x});if(!persist(next))throw Error('브라우저에 저장하지 못했습니다.');$('importMessage').textContent=`${data.length}개 항목을 저장했습니다. 같은 ID의 기존 데이터는 덮어썼습니다.`;show()}catch(err){$('importMessage').textContent='가져오기 실패: '+err.message+' 기존 데이터는 유지됩니다.'}finally{e.target.value=''}};
$('fetchMonster').onclick=async()=>{let id=Number($('apiId').value),name=$('apiName').value.trim();if(!Number.isSafeInteger(id)||id<1||!name){$('apiMessage').textContent='유효한 ID와 확인한 한국어 이름을 입력해 주세요.';return}let button=$('fetchMonster');button.disabled=true;$('apiMessage').textContent='원본 정보를 불러오는 중…';try{let r=await fetch('https://maplestory.io/api/GMS/83/mob/'+id);if(!r.ok)throw Error('원본 서버 응답 '+r.status);let data=await r.json();let m={id:data.id,name,level:data.meta?.level,avoid:data.meta?.evasion,source:'MapleStory.io (한국어 이름 사용자 입력)',version:'GMS 83'};if(!valid(m)||Number(data.id)!==id)throw Error('레벨 또는 회피율이 없거나 ID가 일치하지 않습니다.');fill(normal(m));$('editor').open=true;$('apiMessage').textContent='편집란에 채웠습니다. 값을 확인하고 저장을 눌러 주세요.'}catch(e){$('apiMessage').textContent='불러오기 실패: '+e.message+' · 인터넷 연결과 브라우저 접근 설정을 확인하거나 파일을 가져오세요.'}finally{button.disabled=false}};
$('export').onclick=()=>{let blob=new Blob([JSON.stringify(entries(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='maple-monsters.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
// 입력값 기억 (이 브라우저에만 저장)
function saveCalc(){try{localStorage.setItem(calcKey,JSON.stringify({player:$('player').value,accuracy:$('accuracy').value,job:$('job').value,pill:$('buffPill').checked,bless:$('buffBless').checked,mob:selected}))}catch(e){}}
const calcKey='maple_calc_state_v1';
try{let st=JSON.parse(localStorage.getItem(calcKey)||'null');if(st&&typeof st==='object'){if(typeof st.player==='string'&&/^\d{1,3}$/.test(st.player))$('player').value=st.player;if(typeof st.accuracy==='string'&&/^(\d{1,5}(\.\d+)?)?$/.test(st.accuracy))$('accuracy').value=st.accuracy;if(['warrior','striker','viper'].includes(st.job)){$('job').value=st.job;document.querySelectorAll('[data-job]').forEach(x=>{let on=x.dataset.job===st.job;x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on))})}$('buffPill').checked=st.pill===true;$('buffBless').checked=st.bless===true&&st.pill!==true;if(Number.isSafeInteger(st.mob)&&entries().some(x=>x.id===st.mob))selected=st.mob}}catch(e){}
// 몬스터 목록 키보드 조작: 검색창 ↓ → 목록, ↑↓ 이동, Enter 선택, Esc 검색창으로
$('search').addEventListener('keydown',e=>{let first=$('list').querySelector('.option');if(!first)return;if(e.key==='ArrowDown'){e.preventDefault();($('list').querySelector('.option[tabindex="0"]')||first).focus()}else if(e.key==='Enter'){e.preventDefault();first.click()}});
$('list').addEventListener('keydown',e=>{let items=[...$('list').querySelectorAll('.option')],i=items.indexOf(document.activeElement);if(i<0)return;let next=null;if(e.key==='ArrowDown')next=items[Math.min(items.length-1,i+1)];else if(e.key==='ArrowUp')next=i===0?$('search'):items[i-1];else if(e.key==='Home')next=items[0];else if(e.key==='End')next=items[items.length-1];else if(e.key==='Escape')next=$('search');else if(e.key==='Enter'||e.key===' '){e.preventDefault();items[i].click();$('list').querySelector('[aria-selected="true"]')?.focus();return}if(next){e.preventDefault();items.forEach(x=>x.tabIndex=-1);if(next!==$('search'))next.tabIndex=0;next.focus();if(next!==$('search'))next.scrollIntoView({block:'nearest'})}});
{let q=Number(new URLSearchParams(location.search).get('mob'));if(Number.isSafeInteger(q)&&entries().some(x=>x.id===q))selected=q}
